import{_ as a,o as i,c as e,a0 as n}from"./chunks/framework.DoRPXVp_.js";const c=JSON.parse('{"title":"Agent Sandbox (Pro)","description":"","frontmatter":{"title":"Agent Sandbox (Pro)"},"headers":[],"relativePath":"agent/sandbox-pro.md","filePath":"agent/sandbox-pro.md"}'),t={name:"agent/sandbox-pro.md"};function l(p,s,h,r,o,d){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="agent-sandbox-—-pro-edition" tabindex="-1">Agent Sandbox — Pro Edition <a class="header-anchor" href="#agent-sandbox-—-pro-edition" aria-label="Permalink to &quot;Agent Sandbox — Pro Edition&quot;">​</a></h1><p>The Pro sandbox extends the <a href="/agent/sandbox">Community sandbox</a> with egress filtering, inbound port forwarding, a SOCKS5 proxy, and server-side NATS flow auditing.</p><h2 id="additional-flags" tabindex="-1">Additional Flags <a class="header-anchor" href="#additional-flags" aria-label="Permalink to &quot;Additional Flags&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lattice sandbox start [flags]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Pro-only flags:</span></span>
<span class="line"><span>  --egress-allow   strings   CIDR ranges to allow outbound (default: deny-all)</span></span>
<span class="line"><span>  --forward        strings   Overlay port → host address mappings (e.g. 8080:127.0.0.1:8080)</span></span>
<span class="line"><span>  --proxy-addr     string    Local address for SOCKS5 proxy (e.g. 127.0.0.1:1080)</span></span></code></pre></div><h2 id="egressfilter" tabindex="-1">EgressFilter <a class="header-anchor" href="#egressfilter" aria-label="Permalink to &quot;EgressFilter&quot;">​</a></h2><p>EgressFilter implements <code>PolicyChecker</code> — it intercepts every outbound connection attempt from the gVisor netstack and evaluates it against a CIDR allowlist.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Only allow outbound to the tool service at 10.42.0.10 and HTTPS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lattice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sandbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent-001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --server-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://lattice.internal:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lt-xxx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --egress-allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.42.0.10/32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --egress-allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.0.0.0/0:443</span></span></code></pre></div><p>If no <code>--egress-allow</code> flags are provided, all egress is denied. Denied connections are logged to the audit file.</p><h2 id="forwardlistener" tabindex="-1">ForwardListener <a class="header-anchor" href="#forwardlistener" aria-label="Permalink to &quot;ForwardListener&quot;">​</a></h2><p>Forward inbound connections from the overlay network to a host-local address:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Accept connections on overlay port 8080, forward to localhost:8080</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lattice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sandbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --server-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://lattice.internal:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lt-xxx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --forward</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:127.0.0.1:8080</span></span></code></pre></div><p>Multiple <code>--forward</code> flags are supported.</p><h2 id="socks5-proxy" tabindex="-1">SOCKS5 Proxy <a class="header-anchor" href="#socks5-proxy" aria-label="Permalink to &quot;SOCKS5 Proxy&quot;">​</a></h2><p>Start a SOCKS5 proxy inside the gVisor sandbox. All TCP connections through this proxy are routed through the WireGuard overlay with full policy enforcement and audit logging.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lattice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sandbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browser-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --server-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://lattice.internal:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lt-xxx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --proxy-addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:1080</span></span></code></pre></div><p>In your agent process:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ALL_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">socks5://127.0.0.1:1080</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://internal-api.example.com/data</span></span></code></pre></div><h2 id="nats-flow-audit-server-side" tabindex="-1">NATS Flow Audit (Server-side) <a class="header-anchor" href="#nats-flow-audit-server-side" aria-label="Permalink to &quot;NATS Flow Audit (Server-side)&quot;">​</a></h2><p>Pro adds server-side persistence of network flow events. The sandbox publishes to <code>lattice.audit.flow</code> on NATS; the control plane&#39;s <code>AuditConsumer</code> persists events to the <code>la_flow_events</code> database table.</p><blockquote><p><strong>Status:</strong> Server-side pipeline is complete (<code>AuditConsumer</code> + <code>la_flow_events</code>). The sandbox-side <code>natsAuditWriter</code> is in development — sandbox currently writes to local file only.</p></blockquote><p>Query audit events via the dashboard or API:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/audit/flow?agentName=agent-001&amp;from=2026-05-18T00:00:00Z</span></span></code></pre></div>`,22)])])}const g=a(t,[["render",l]]);export{c as __pageData,g as default};
